--
-- Name: enforce_dispute_vote_eligibility(); Type: FUNCTION; Schema: public; Owner: grassland
--

CREATE FUNCTION public.enforce_dispute_vote_eligibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_judge_id uuid;
    target_organization_id uuid;
BEGIN
    SELECT j.id, d.organization_id
    INTO target_judge_id, target_organization_id
    FROM judge j
    JOIN dispute_panel_assignment p
      ON p.dispute_id = NEW.dispute_id
     AND p.round = NEW.round
     AND p.judge_account_id = j.account_id
    JOIN dispute_case d ON d.id = p.dispute_id
    WHERE j.account_id = NEW.judge_account_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'judge is not eligible to vote on this panel';
    END IF;

    PERFORM pg_advisory_xact_lock(judge_conflict_lock_key(target_judge_id, target_organization_id));

    PERFORM 1
    FROM judge j
    JOIN dispute_panel_assignment p
      ON p.dispute_id = NEW.dispute_id
     AND p.round = NEW.round
     AND p.judge_account_id = j.account_id
    JOIN dispute_case d ON d.id = p.dispute_id
    WHERE j.account_id = NEW.judge_account_id
      AND j.active = true
      AND j.ops_admitted = true
      AND d.status = 'voting'
      AND d.round = NEW.round
      AND d.appeal_state <> 'escalated'
      AND (j.organization_id IS NULL OR j.organization_id <> d.organization_id)
      AND NOT EXISTS (
          SELECT 1
          FROM judge_conflict conflict
          WHERE conflict.judge_id = j.id
            AND conflict.organization_id = d.organization_id)
    FOR SHARE OF j, p, d;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'judge is not eligible to vote on this panel';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_dispute_vote_eligibility() OWNER TO grassland;

--
-- Name: enforce_panel_assignment_eligibility(); Type: FUNCTION; Schema: public; Owner: grassland
--

CREATE FUNCTION public.enforce_panel_assignment_eligibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_judge_id uuid;
    target_organization_id uuid;
BEGIN
    SELECT j.id, d.organization_id
    INTO target_judge_id, target_organization_id
    FROM judge j
    JOIN dispute_case d ON d.id = NEW.dispute_id
    WHERE j.account_id = NEW.judge_account_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'judge is not eligible for panel assignment';
    END IF;

    PERFORM pg_advisory_xact_lock(judge_conflict_lock_key(target_judge_id, target_organization_id));

    PERFORM 1
    FROM judge j
    JOIN dispute_case d ON d.id = NEW.dispute_id
    WHERE j.account_id = NEW.judge_account_id
      AND j.active = true
      AND j.ops_admitted = true
      AND j.eligibility_tier >= 5
      AND (j.organization_id IS NULL OR j.organization_id <> d.organization_id)
      AND NOT EXISTS (
          SELECT 1
          FROM judge_conflict conflict
          WHERE conflict.judge_id = j.id
            AND conflict.organization_id = d.organization_id)
    FOR SHARE OF j, d;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'judge is not eligible for panel assignment';
    END IF;
    RETURN NEW;
END;
$$;


