--
-- Name: fence_legacy_credit_consume(); Type: FUNCTION; Schema: public; Owner: grassland
--

CREATE FUNCTION public.fence_legacy_credit_consume() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_state varchar(16);
    current_source varchar(16);
    current_consume_transaction_id uuid;
BEGIN
    IF NEW.type <> 'consume' OR NEW.operation_id IS NULL THEN
        RETURN NEW;
    END IF;

    INSERT INTO credits_consume_operation(
        operation_id, account_id, feature, state,
        consume_transaction_id, consume_balance_after, charge_source,
        created_at, updated_at
    )
    VALUES (
        NEW.operation_id, NEW.account_id, COALESCE(NEW.feature, 'unknown'), 'consumed',
        NEW.id, NEW.balance_after, 'paid', NEW.created_at, NEW.created_at
    )
    ON CONFLICT (operation_id) DO NOTHING;

    SELECT state, charge_source, consume_transaction_id
    INTO current_state, current_source, current_consume_transaction_id
    FROM credits_consume_operation
    WHERE operation_id = NEW.operation_id
    FOR UPDATE;

    IF current_state = 'open' THEN
        UPDATE credits_consume_operation
        SET state = 'consumed',
            charge_source = 'paid',
            consume_transaction_id = NEW.id,
            consume_balance_after = NEW.balance_after,
            updated_at = now()
        WHERE operation_id = NEW.operation_id;
        RETURN NEW;
    END IF;

    -- The insert above owns a newly-created fence. A committed quota/compensation or a paid
    -- transaction with another id means a concurrent writer already owns this operation.
    IF current_state <> 'consumed'
            OR current_source IS DISTINCT FROM 'paid'
            OR current_consume_transaction_id IS DISTINCT FROM NEW.id THEN
        RAISE EXCEPTION 'credit consume operation % is already owned', NEW.operation_id
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fence_legacy_credit_consume() OWNER TO grassland;

--
-- Name: freeze_application_task_context(); Type: FUNCTION; Schema: public; Owner: grassland
--

CREATE FUNCTION public.freeze_application_task_context() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'accepted' AND OLD.status <> 'accepted' AND NEW.task_context_snapshot IS NULL THEN
        SELECT jsonb_build_object(
            'taskId', t.id, 'taskVersion', t.version, 'title', t.title,
            'description', t.description, 'contentForm', t.content_form,
            'platform', t.platform, 'storeId', t.store_id,
            'applicationId', NEW.id, 'recommenderAccountId', NEW.recommender_account_id,
            'bountyCents', NEW.bounty_cents,
            'freebieDepositCents', COALESCE(NEW.freebie_deposit_cents, 0),
            'acceptedAt', COALESCE(NEW.decided_at, now()),
            'requirements', COALESCE(tv.requirements, '{}'::jsonb)
        ) INTO NEW.task_context_snapshot
        FROM task t
        LEFT JOIN task_version tv ON tv.task_id = t.id AND tv.version = t.version
        WHERE t.id = NEW.task_id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.freeze_application_task_context() OWNER TO grassland;

