--
-- Name: normalize_ai_credit_compensation_run_scope(); Type: FUNCTION; Schema: public; Owner: grassland
--

CREATE FUNCTION public.normalize_ai_credit_compensation_run_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.standalone THEN
        NEW.actual_run_id := NULL;
        IF NEW.run_id IS DISTINCT FROM NEW.consume_operation_id THEN
            RAISE EXCEPTION 'standalone compensation run sentinel must equal consume operation'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        IF NEW.actual_run_id IS NULL THEN
            NEW.actual_run_id := NEW.run_id;
        END IF;
        IF NEW.actual_run_id IS DISTINCT FROM NEW.run_id THEN
            RAISE EXCEPTION 'run-backed compensation scope mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.normalize_ai_credit_compensation_run_scope() OWNER TO grassland;

