    operation_id text NOT NULL,
    account_id uuid NOT NULL,
    feature text NOT NULL,
    state character varying(16) NOT NULL,
    consume_transaction_id uuid,
    refund_transaction_id uuid,
    consume_balance_after integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    charge_source character varying(16),
    quota_day date,
    quota_limit integer,
    policy_version bigint,
    ai_quota_multiplier_bps integer,
    quota_consume_transaction_id uuid,
    quota_refund_transaction_id uuid,
    usage_priced boolean DEFAULT false NOT NULL,
    credits_cents_policy_version character varying(64),
    credits_cents_rounding character varying(16),
    cents_numerator bigint,
    credits_denominator bigint,
    max_cents_per_operation bigint,
    reserved_cents bigint,
    reserved_credits integer,
    actual_cents bigint,
    actual_credits integer,
    adjustment_credits integer,
    settlement_transaction_id uuid,
    settled_at timestamp with time zone,
    CONSTRAINT chk_credits_consume_operation_lifecycle CHECK (((((state)::text = 'open'::text) AND (consume_transaction_id IS NULL) AND (refund_transaction_id IS NULL) AND (consume_balance_after IS NULL) AND (quota_consume_transaction_id IS NULL) AND (quota_refund_transaction_id IS NULL) AND (charge_source IS NULL)) OR (((state)::text = ANY ((ARRAY['consumed'::character varying, 'settled'::character varying])::text[])) AND (refund_transaction_id IS NULL) AND (quota_refund_transaction_id IS NULL) AND ((((charge_source)::text = 'paid'::text) AND (consume_transaction_id IS NOT NULL) AND (consume_balance_after IS NOT NULL) AND (quota_consume_transaction_id IS NULL)) OR (((charge_source)::text = 'quota'::text) AND (consume_transaction_id IS NULL) AND (consume_balance_after IS NOT NULL) AND (quota_consume_transaction_id IS NOT NULL) AND (quota_day IS NOT NULL) AND (quota_limit IS NOT NULL) AND (policy_version IS NOT NULL) AND (ai_quota_multiplier_bps IS NOT NULL))) AND (((state)::text <> 'settled'::text) OR usage_priced)) OR (((state)::text = 'compensated'::text) AND (((consume_transaction_id IS NULL) AND (refund_transaction_id IS NULL) AND (consume_balance_after IS NULL) AND (quota_consume_transaction_id IS NULL) AND (quota_refund_transaction_id IS NULL) AND (charge_source IS NULL)) OR (((charge_source)::text = 'paid'::text) AND (consume_transaction_id IS NOT NULL) AND (refund_transaction_id IS NOT NULL) AND (consume_balance_after IS NOT NULL) AND (quota_consume_transaction_id IS NULL) AND (quota_refund_transaction_id IS NULL)) OR (((charge_source)::text = 'quota'::text) AND (consume_transaction_id IS NULL) AND (refund_transaction_id IS NULL) AND (consume_balance_after IS NOT NULL) AND (quota_consume_transaction_id IS NOT NULL) AND (quota_refund_transaction_id IS NOT NULL)))))),
    CONSTRAINT chk_credits_consume_operation_usage_policy CHECK ((((NOT usage_priced) AND (credits_cents_policy_version IS NULL) AND (credits_cents_rounding IS NULL) AND (cents_numerator IS NULL) AND (credits_denominator IS NULL) AND (max_cents_per_operation IS NULL) AND (reserved_cents IS NULL) AND (reserved_credits IS NULL) AND (actual_cents IS NULL) AND (actual_credits IS NULL) AND (adjustment_credits IS NULL) AND (settlement_transaction_id IS NULL) AND (settled_at IS NULL)) OR (usage_priced AND (credits_cents_policy_version IS NOT NULL) AND ((credits_cents_rounding)::text = ANY ((ARRAY['HALF_UP'::character varying, 'HALF_EVEN'::character varying, 'DOWN'::character varying, 'UP'::character varying])::text[])) AND (cents_numerator > 0) AND (credits_denominator > 0) AND (max_cents_per_operation > 0) AND ((reserved_cents >= 0) AND (reserved_cents <= max_cents_per_operation)) AND (reserved_credits >= 0) AND ((((state)::text <> 'settled'::text) AND (actual_cents IS NULL) AND (actual_credits IS NULL) AND (adjustment_credits IS NULL) AND (settlement_transaction_id IS NULL) AND (settled_at IS NULL)) OR (((state)::text = 'settled'::text) AND ((actual_cents >= 0) AND (actual_cents <= max_cents_per_operation)) AND (actual_credits >= 0) AND (adjustment_credits IS NOT NULL) AND (settled_at IS NOT NULL)))))),
    CONSTRAINT credits_consume_operation_ai_quota_multiplier_bps_check CHECK (((ai_quota_multiplier_bps IS NULL) OR ((ai_quota_multiplier_bps >= 1000) AND (ai_quota_multiplier_bps <= 100000)))),
    CONSTRAINT credits_consume_operation_charge_source_check CHECK (((charge_source)::text = ANY ((ARRAY['quota'::character varying, 'paid'::character varying])::text[]))),
    CONSTRAINT credits_consume_operation_policy_version_check CHECK (((policy_version IS NULL) OR (policy_version >= 1))),
    CONSTRAINT credits_consume_operation_quota_limit_check CHECK (((quota_limit IS NULL) OR (quota_limit >= 0))),
    CONSTRAINT credits_consume_operation_state_check CHECK (((state)::text = ANY ((ARRAY['open'::character varying, 'consumed'::character varying, 'settled'::character varying, 'compensated'::character varying])::text[])))
);


ALTER TABLE public.credits_consume_operation OWNER TO grassland;

