    CONSTRAINT credits_quota_transaction_ai_quota_multiplier_bps_check CHECK (((ai_quota_multiplier_bps >= 1000) AND (ai_quota_multiplier_bps <= 100000))),
    CONSTRAINT credits_quota_transaction_delta_used_check CHECK ((delta_used = ANY (ARRAY['-1'::integer, 1]))),
    CONSTRAINT credits_quota_transaction_policy_version_check CHECK ((policy_version >= 1)),
