    CONSTRAINT credits_quota_transaction_source_check CHECK (((source)::text = 'quota'::text)),
    CONSTRAINT credits_quota_transaction_type_check CHECK (((type)::text = ANY ((ARRAY['consume'::character varying, 'refund'::character varying])::text[]))),
    CONSTRAINT credits_quota_transaction_used_after_check CHECK ((used_after >= 0))
);


