--
-- Name: reputation_level_rule; Type: TABLE; Schema: public; Owner: grassland
--

CREATE TABLE public.reputation_level_rule (
    level_number smallint NOT NULL,
    level_code character varying(3) NOT NULL,
    title character varying(32) NOT NULL,
    min_completed integer NOT NULL,
    min_completion_rate numeric(6,5) NOT NULL,
    min_average_score numeric(3,2),
    invite_only boolean DEFAULT false NOT NULL,
    judge_eligible boolean DEFAULT false NOT NULL,
    task_priority_weight integer NOT NULL,
    settlement_delay_days integer NOT NULL,
    commission_bonus_bps integer NOT NULL,
    ai_quota_multiplier_bps integer NOT NULL,
    premium_support boolean DEFAULT false NOT NULL,
    benefits jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT ck_reputation_level_ai_quota CHECK (((ai_quota_multiplier_bps >= 1000) AND (ai_quota_multiplier_bps <= 100000))),
    CONSTRAINT ck_reputation_level_benefits CHECK (((jsonb_typeof(benefits) = 'array'::text) AND (jsonb_array_length(benefits) <= 16))),
    CONSTRAINT ck_reputation_level_code CHECK (((level_code)::text = ('Lv'::text || (level_number)::text))),
    CONSTRAINT ck_reputation_level_commission CHECK (((commission_bonus_bps >= 0) AND (commission_bonus_bps <= 10000))),
    CONSTRAINT ck_reputation_level_completed CHECK (((min_completed >= 0) AND (min_completed <= 1000000))),
    CONSTRAINT ck_reputation_level_invite CHECK ((invite_only = (level_number = 5))),
    CONSTRAINT ck_reputation_level_judge CHECK ((judge_eligible = (level_number = 5))),
    CONSTRAINT ck_reputation_level_number CHECK (((level_number >= 1) AND (level_number <= 5))),
    CONSTRAINT ck_reputation_level_priority CHECK (((task_priority_weight >= 1) AND (task_priority_weight <= 10000))),
    CONSTRAINT ck_reputation_level_rate CHECK (((min_completion_rate >= (0)::numeric) AND (min_completion_rate <= (1)::numeric))),
    CONSTRAINT ck_reputation_level_score CHECK (((min_average_score IS NULL) OR ((min_average_score >= (0)::numeric) AND (min_average_score <= (5)::numeric)))),
    CONSTRAINT ck_reputation_level_settlement CHECK (((settlement_delay_days >= 0) AND (settlement_delay_days <= 30))),
    CONSTRAINT ck_reputation_level_title CHECK (((char_length(btrim((title)::text)) >= 1) AND (char_length(btrim((title)::text)) <= 32)))
);


